const input = $input.first().json;
const body = input.body ?? input;
const task = body.task ?? body;
const customFields = Array.isArray(task.custom_fields) ? task.custom_fields : [];
const fieldValue = (name) => customFields.find((f) => String(f.name || '').toLowerCase() === name)?.value ?? null;
const externalId = task.id ?? task.task_id ?? null;
if (!externalId) {
  return [{ json: { accepted: false, error: 'Missing ClickUp task id', expected: 'task.id or task.task_id' } }];
}
const createdRaw = task.date_created ?? task.created_at ?? new Date().toISOString();
const createdAt = Number.isFinite(Number(createdRaw)) && String(createdRaw).length >= 10
  ? new Date(Number(createdRaw)).toISOString()
  : new Date(createdRaw).toISOString();
const rawSource = String(fieldValue('lead source') ?? task.source ?? 'other').toLowerCase();
const source = ['meta', 'organic', 'referral', 'other'].includes(rawSource) ? rawSource : 'other';
const status = String(task.status?.status ?? task.status ?? '').toLowerCase();
const stageMap = { qualified: 'qualified', discovery_scheduled: 'discovery_scheduled', discovery_attended: 'discovery_attended', ambition_interview: 'ambition_interview', architect_session: 'architect_session', paid: 'paid' };
const stage = stageMap[status.replaceAll(' ', '_')] ?? null;
return [{ json: { accepted: true, mode: 'preview_only', lead: { id: `clickup_${externalId}`, external_clickup_id: String(externalId), created_at: createdAt, source, campaign_id: fieldValue('campaign id') ? String(fieldValue('campaign id')) : null }, stage_event: stage ? { stage, occurred_at: new Date().toISOString(), external_event_id: `clickup_${externalId}_${stage}` } : null, note: 'Preview only: connect an approved PostgreSQL upsert after confirming ClickUp field IDs and stage mapping.' } }];
